eq('cycle broken A10', s.get('A10'), 7);
eq('cycle broken C10', s.get('C10'), 8);
put('A11', '=A11'); eq('self ref', s.get('A11'), '#CYCLE!');

// updates propagate
put('M1', '1'); put('M2', '=M1*2'); put('M3', '=M2*2');
put('M1', '5'); eq('propagates', s.get('M3'), 20);
put('N1', '=M1'); eq('display 5', s.display('N1'), '5');

// copy with relative and absolute references
const c = createSheet();
c.set('A1', '1'); c.set('B1', '2'); c.set('A2', '=A1+$A$1');
c.set('B2', '=A1*B$1');
c.copy('A2', 'C3');
eq('copy shifted', c.raw('C3'), '=B2+$A$1');
c.copy('B2', 'J30');
eq('copy keeps $ row', c.raw('J30'), '=I29*J$1');
c.copy('A2', 'J30');
eq('copy out of grid', c.get('J30'), '#REF!');
c.set('K1', '=A1');
eq('invalid typed ref', c.get('K1'), '#REF!');
c.set('Z9', 'plain');
c.copy('Z9', 'A5');
eq('copy text', c.get('A5'), 'plain');

// undo / redo
const u = createSheet();
u.set('A1', '1');
u.set('A1', '2');
u.undo();
eq('undo', u.get('A1'), 1);
u.redo();
eq('redo', u.get('A1'), 2);
u.undo(); u.set('B1', 'x');
u.redo();
eq('new set drops redo', u.get('A1'), 1);
for (let i = 0; i < 150; i++) u.set('C1', String(i));
let undone = 0;
for (let i = 0; i < 200; i++) { const before = u.raw('C1'); u.undo(); if (u.raw('C1') !== before) undone++; }
eq('undo limited to 100', undone, 100);

// CSV
const csv = createSheet();
csv.set('A1', 'a,b'); csv.set('B1', 'say "hi"'); csv.set('A2', '=1/3'); csv.set('B2', 'x\ny');
eq('csv', csv.toCSV(), '"a,b","say ""hi"""\n0.3333333333,"x\ny"');
eq('csv empty', createSheet().toCSV(), '');

// persistence helpers
const p = createSheet();
p.set('D4', '=2*21');
const restored = createSheet();
restored.load(JSON.parse(JSON.stringify(p.dump())));
eq('dump/load', restored.get('D4'), 42);

// invalid refs in API
let threw = false;
try { s.set('K1', '1'); } catch { threw = true; }
eq('set invalid throws', threw, true);
eq('get invalid', s.get('K1'), '#REF!');

